import{z as l,x as i,o as s,c as d,q as t,j as r,D as E,d as A,s as B,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SSD 内部并行、GC 与磨损","description":"","frontmatter":{"title":"SSD 内部并行、GC 与磨损","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssd-gc-wear.md","filePath":"cs/ssd-gc-wear.md","lastUpdated":1791413859000}'),D={name:"cs/ssd-gc-wear.md"};function p(C,a,c,S,m,h){const n=i("Mermaid");return s(),d("div",null,[a[2]||(a[2]=t('<h1 id="ssd-内部并行、gc-与磨损" tabindex="-1">SSD 内部并行、GC 与磨损 <a class="header-anchor" href="#ssd-内部并行、gc-与磨损" aria-label="Permalink to &quot;SSD 内部并行、GC 与磨损&quot;">​</a></h1><div class="epigraph"><p>多通道、多颗粒、多 plane 把页编程叠起来才有带宽；垃圾回收搬走有效页再擦块，磨损均衡避免热逻辑地址写死同一物理块。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/nand-ftl">上一课</a>留下无效页与 L2P。缺口是性能与寿命：<strong>内部并行</strong>从哪来，<strong>GC</strong>何时抢用户写，<strong>磨损</strong>如何摊。否则「SSD 很快」只是广告，写放大没有定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NAND 页编程延迟远大于 DRAM 行命中，靠通道/die/plane 交错。GC：空闲块低于阈值时，选牺牲块、读有效页、写到新块、擦除牺牲块——与用户写争带宽，写放大 WA = 物理编程量 / 主机写入量。磨损：每块擦写次数有上限，热映射必须搬动物理位置。缺口不是再定义 FTL，而是这三项如何耦合。</p><p><span class="marginnote">写放大给个数字实例：主机写 1 GB、盘内部实际编程了 3 GB（含 GC 搬页），WA = 3。理想下限是 1（搬得越少越接近），代价是把可用容量的一部分留作超配。所以「买 1 TB 实际只有约 930 GB」不是缺斤短两，那部分空间就是用来压低 WA 与延缓磨损的。</span></p><p>TRIM/unmap 让主机声明 LBA 无用，减少 GC 搬移。DRAM 缓存映射加速，掉电靠电容刷回——与<a href="/cs/nvm-persistent">持久域</a>同类问题。</p><h3 id="gc-不是「磁盘碎片整理」" tabindex="-1">GC 不是「磁盘碎片整理」 <a class="header-anchor" href="#gc-不是「磁盘碎片整理」" aria-label="Permalink to &quot;GC 不是「磁盘碎片整理」&quot;">​</a></h3><p>HDD 碎片整理移动扇区以缩短寻道；SSD 没有寻道，GC 是擦除约束下的空间回收。把二者当同一 OS 工具，会在闪存上做无益的强制搬移。</p><p><span class="marginnote">CA:AQA 与 COD 讨论闪存与 SSD。写放大与磨损是存储系统常识。本课不引用虚构的百分数保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>调度：空闲时 GC，负载时让用户写。并行：把大写条带化到通道。磨损均衡：静态（搬冷块）与动态（新写落在年轻块）。超配（OP）提供空闲块，降 WA。ECC 失败则退休块，L2P 改指。</p><p><span class="marginnote">常见误区：「盘快满了变慢是玄学」。机制很直白：空闲块不足时 GC 被迫在每个用户写请求中间穿插搬页，带宽被后台抢走。定期 TRIM（让系统告诉盘哪些页已死）能让 GC 挑到「几乎全死」的块、少搬有效页——这就是为什么长期不 TRIM 的盘越用越慢。</span></p>',13)),(s(),r(o,null,{default:E(()=>[B(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOST%5B%22%E4%B8%BB%E6%9C%BA%E5%86%99%22%5D%20--%3E%20STRIPE%5B%22%E9%80%9A%E9%81%93%20%2F%20die%20%E6%9D%A1%E5%B8%A6%22%5D%0A%20%20INV%5B%22%E6%97%A0%E6%95%88%E9%A1%B5%E5%A0%86%E7%A7%AF%22%5D%20--%3E%20GC%5B%22%E6%90%AC%E6%9C%89%E6%95%88%E9%A1%B5%20%2B%20%E6%93%A6%E9%99%A4%22%5D%0A%20%20GC%20--%3E%20WA%5B%22%E5%86%99%E6%94%BE%E5%A4%A7%22%5D%0A%20%20WEAR%5B%22%E6%93%A6%E5%86%99%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20EQ%5B%22%E7%A3%A8%E6%8D%9F%E5%9D%87%E8%A1%A1%22%5D%0A%20%20EQ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AHDD%20%E4%BB%8D%E6%9C%89%E5%AF%BB%E9%81%93%E5%87%A0%E4%BD%95%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 DRAM FR-FCFS 对照：这里优化的是擦除与编程队列，没有行缓冲，但有 plane 忙闲。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"后课 HDD 用柱面/磁头/扇区与寻道；SSD 用 LBA 平板。PCIe/NVMe 把多队列打到这块并行上。本课先把介质控制器做完。BIST/工厂坏块表在出厂；现场再成长坏块由 FTL 处理。",-1)),(s(),r(o,null,{default:E(()=>[B(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREE%5B%22%E7%A9%BA%E9%97%B2%E5%9D%97%E4%BD%8E%E4%BA%8E%E9%98%88%E5%80%BC%22%5D%20--%3E%20PICK%5B%22%E9%80%89%E7%89%BA%E7%89%B2%E5%9D%97%EF%BC%9A%E6%97%A0%E6%95%88%E9%A1%B5%E5%8D%A0%E6%AF%94%E6%9C%80%E9%AB%98%22%5D%0A%20%20PICK%20--%3E%20READ%5B%22%E8%AF%BB%E5%87%BA%E5%85%B6%E4%B8%AD%E7%9A%84%E6%9C%89%E6%95%88%E9%A1%B5%22%5D%0A%20%20READ%20--%3E%20WRITE%5B%22%E6%9C%89%E6%95%88%E9%A1%B5%E9%87%8D%E5%86%99%E5%88%B0%E6%96%B0%E5%9D%97%22%5D%0A%20%20WRITE%20--%3E%20ERASE%5B%22%E6%95%B4%E5%9D%97%E6%93%A6%E9%99%A4%EF%BC%8C%E5%BD%92%E5%85%A5%E7%A9%BA%E9%97%B2%E6%B1%A0%22%5D%0A%20%20ERASE%20--%3E%20FREE%0A%20%20TRIM%5B%22%E4%B8%BB%E6%9C%BA%20TRIM%EF%BC%9A%E5%A3%B0%E6%98%8E%20LBA%20%E5%B7%B2%E6%AD%BB%22%5D%20--%3E%20PICK%0A%20%20OP%5B%22%E8%B6%85%E9%85%8D%20OP%EF%BC%9A%E9%A2%84%E7%95%99%E6%9C%AA%E6%98%A0%E5%B0%84%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20FREE%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">GC 一轮的账可以这样算：牺牲块若有 128 页、其中只有 8 页还活着，搬 8 页就能换回一整块的擦写额度——很划算；若 120 页都活着，就要搬 120 页才擦一块——写放大达十几倍且用户写被卡住。牺牲块选择策略整张图的核心就是「挑死页最多的块」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某厂商主控固件当标准，不讨论 QLC 读干扰的全部模拟。不进入数据中心运维更换策略的财务表。</p><p>后课默认：SSD 带宽来自闪存并行；GC 与磨损均衡制造写放大和后台流量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并行掩盖页编程延迟；GC 回收擦除块并产生写放大。</li><li>磨损均衡打散热写；TRIM 减少无用搬移。</li><li>不是磁盘碎片整理。</li><li>出处：Patterson and Hennessy, COD；Hennessy and Patterson, CA:AQA。</li></ul>',6))])}const P=l(D,[["render",p]]);export{u as __pageData,P as default};
